import xml.etree.ElementTree as ET


def get_all_params_under_class_name(scf_file_content, class_name):
    """
    Get all parameters and their values from scf for a given class
    :param class_name: scf class name: eg: "com.nokia.srbts.nrbts:NRCELL", "com.nokia.asi:CELL"
    :return: list of dicts contains keys: 'dist_name', 'params'
        eg:
            [
                {
                    "dist_name":"MRBTS-76065/MNL-1/MNLENT-1/FEATCADM-1",
                    "params":{
                    "actAldSharing":"false",
                    "actAldSwUpdate":"false",
                    "actAntennaPathDelayMeasurement":"false",
                    "actApts":"false",
                    ....
                    }
                },
               ...
            ]
    """
    scf_xml = ET.fromstring(scf_file_content)
    all_params = []
    all_classes = scf_xml.findall(".//*[@class='{}']".format(class_name))
    for class_item in all_classes:
        class_params = {}
        for param in class_item:
            if 'list' in param.tag:
                class_params[param.attrib['name']] = []
                for item in param:
                    item_results = {}
                    for elem in item:
                        item_results[elem.attrib['name']] = elem.text
                    class_params[param.attrib['name']].append(item_results)
            else:
                class_params[param.attrib['name']] = param.text
        all_params.append({'dist_name': class_item.attrib['distName'], 'params': class_params})
    return all_params
